    for (i = 0; i < CPL.pursue.length; i++) if (t.indexOf(norm(CPL.pursue[i])) !== -1) p++;
    for (i = 0; i < CPL.withdraw.length; i++) if (t.indexOf(norm(CPL.withdraw[i])) !== -1) w++;
